/**
 * Calculates the UTC offset (in minutes) for the passed in time zone.
 * @note The reason this needs year, month, day, hours, minutes, and seconds is because The offset changes during the two days of the year where daylight savings time changes.
 * @note You can see the list of supported time zones by running ['utc'].concat(Intl.supportedValuesOf('timeZone')) in your browser console.
 * @param year The year for the calc.
 * @param month The month for the calc.
 * @param day The day for the calc.
 * @param hours The hours for the calc.
 * @param minutes The minutes for the calc.
 * @param seconds The seconds for the calc.
 * @param timeZone The time zone for the calc.
 * @returns The offset in minutes between the time zone and UTC for the specified date.
 * This mimics the strange behavior of Date.prototype.getTimezoneOffset() which returns a positive number
 * to represent a negative offset.
 */
export function getOffsetForTimeZone(year, month, day, hours, minutes, seconds, timeZone) {
    if (timeZone.toLowerCase() === 'utc') {
        //The offset for UTC is always 0.
        return 0;
    }
    //The potential for two different offsets during the same day is a hassle to deal with which is why we see
    //more complicated code here.
    //Get the offsets for day+1 and the day-1 so we know the two possible offsets for the day.
    const offset1 = getOffsetForTz(year, month, day + 1, timeZone);
    const offset2 = getOffsetForTz(year, month, day - 1, timeZone);
    if (offset1 === offset2) {
        //They are the same! Easy! We are done.
        return offset1;
    }
    else {
        //We need to convert the Date to UTC using offset2 and then format it for that timeZone.
        const format2 = utcDateToTimeZone(new Date(Date.UTC(year, month, day, hours, minutes + offset2, seconds)), timeZone);
        if (Number(format2.hour) === hours && Number(format2.minute) === minutes) {
            //The formatted hours and minutes match the passed in hours and minutes so offset2 is the answer
            //NOTE: There is a case on daylight savings time day where format2 and format1 are the exact same result.
            //We need to return offset2 in that case rather than offset1 because otherwise we get the wrong answer.
            return offset2;
        }
        else {
            //If it isn't offset2, it must be offset1
            return offset1;
        }
    }
}
/**
 * This gets the the offset for the timezone, but only gives the offset at 12:00 AM.
 * This function is purposefully not exported.
 */
function getOffsetForTz(year, month, day, timeZone) {
    //What I want to do instead is
    const utcDate = new Date(Date.UTC(year, month, day, 0, 0, 0));
    const map = utcDateToTimeZone(utcDate, timeZone);
    const newMilliseconds = Date.parse(`${map.year}-${map.month}-${map.day}T${map.hour}:${map.minute}:${map.second}.000Z`);
    const calculatedOffset = (utcDate.getTime() - newMilliseconds) / 60000;
    return calculatedOffset;
}
/**
 * Takes in a utcDate, and converts it to the timeZone passed in.
 * The returned object has {year, month, day, hour, minute, second} where
 * each is a string value.
 * This function is purposefully not exported.
 */
function utcDateToTimeZone(utcDate, outputTimeZone) {
    const dtFormat = new Intl.DateTimeFormat('en-US', {
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        timeZone: outputTimeZone
    });
    const parts = dtFormat.formatToParts(utcDate);
    const map = {};
    for (const part of parts) {
        map[part.type] = part.value;
    }
    return map;
}
/**
 * Converts a dateTimeStamp from one time zone to another.
 *
 * @note You can see the list of supported time zones by running ['utc'].concat(Intl.supportedValuesOf('timeZone')) in your browser console.
 * @param inputDate The DateTimeStamp object you want to convert.
 * @param outputTimeZone The time zone of the return DateTimeStamp
 * @returns A DateTimeStamp object with the altered time zone.
 */
export function convertTimeZone(inputDate, outputTimeZone) {
    //It's a bit odd that the inputs and outputs of this function are not Date objects.
    //The reason is because JavaScript Date objects have two modes: UTC, and Local.  But the input and output of this function
    //can be neither UTC nor Local.  To remove the confusion completely, we built our own.
    //At first we were thinking we could just use the local stuff in the date object, but that breaks when
    //you put in 2:30AM on March 10 2024 because that doesn't exist in PST timezone, even though it might actually
    //exist in the timezone that it is representing.
    //Get the offset
    const inputsOffset = getOffsetForTimeZone(inputDate.year, inputDate.monthIndex, inputDate.day, inputDate.hours, inputDate.minutes, inputDate.seconds, inputDate.timeZone);
    //Use the offset to convert the inputDate to a UTC Date
    const inputAsUtc = new Date(Date.UTC(inputDate.year, inputDate.monthIndex, inputDate.day, inputDate.hours, inputDate.minutes + inputsOffset, inputDate.seconds));
    //Convert the UTC Date to the outputTimeZone
    //utcDateToTimeZone gives off the actual month number, not the monthIndex.
    const formattedPieces = utcDateToTimeZone(inputAsUtc, outputTimeZone);
    const outputDateTimeStamp = {
        year: Number(formattedPieces.year),
        monthIndex: Number(formattedPieces.month) - 1,
        day: Number(formattedPieces.day),
        hours: Number(formattedPieces.hour),
        minutes: Number(formattedPieces.minute),
        seconds: Number(formattedPieces.day),
        timeZone: outputTimeZone
    };
    return outputDateTimeStamp;
}
/**
 * Converts a date time stamp into a JS Date object that can be passed into Neon components with the timeZone neonDateTimeZone.
 *
 * @note You can see the list of supported time zones by running ['utc'].concat(Intl.supportedValuesOf('timeZone')) in your browser console.
 * @param dtStamp The date time stamp to convert.
 * @param neonDateTimeZone The time zone of the date you want to display things in Neon components with.
 * @returns A Date object where the getHours() and getMinutes() functions will be in the time zone neonDateTimeZone.
 */
export function convertToNeonDate(dtStamp, neonDateTimeZone) {
    const convertedDateTimeStamp = convertTimeZone(dtStamp, neonDateTimeZone);
    return new Date(convertedDateTimeStamp.year, convertedDateTimeStamp.monthIndex, convertedDateTimeStamp.day, convertedDateTimeStamp.hours, convertedDateTimeStamp.minutes, convertedDateTimeStamp.seconds);
}
/**
 * Converts a JS Date object represented the time zone neonDateTimeZone into a DateTimeStamp with the time zone outputTimeZone.
 *
 * @note You can see the list of supported time zones by running ['utc'].concat(Intl.supportedValuesOf('timeZone')) in your browser console.
 * @param neonDate The Date object to convert.
 * @param neonDateTimeZone The time zone of the getHours() and getMinutes() functions in the neonDate object.
 * @param outputTimeZone The time zone of DateTime stamp returned by this function.
 * @returns The converted date time stamp.
 */
export function convertFromNeonDate(neonDate, neonDateTimeZone, outputTimeZone) {
    return convertTimeZone({
        year: neonDate.getFullYear(),
        monthIndex: neonDate.getMonth(),
        day: neonDate.getDate(),
        hours: neonDate.getHours(),
        minutes: neonDate.getMinutes(),
        seconds: neonDate.getSeconds(),
        timeZone: neonDateTimeZone
    }, outputTimeZone);
}
